using System;
using System.Windows.Forms;
using System.Threading;
using System.Globalization;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Linq;
using System.Text;
using DevExpress.XtraGrid.Views.Grid.ViewInfo;

namespace CFCAIM
{
    public partial class Test2 : Form
    {
        public Test2()
        {
            ////InitializeComponent();
            ////// This line of code is generated by Data Source Configuration Wizard
            ////pivotGridControl1.DataSource = new System.Collections.Generic.List<CFCAIMCore.Entity.SampleInfo>() /* TODO: Assign the real data here.*/;
            ///
            InitializeComponent();
            Random rnd = new Random();
            DataTable table = new DataTable();
            table.Columns.Add("Value1");
            table.Columns.Add("Value2");
            for (int i = 0; i < rnd.Next(100); i++)
            {
                table.Rows.Add(new object[] { "Custom" + rnd.Next(15), "Address" + rnd.Next(20) });
            }
            gridControl2.DataSource = table;

            gridView2.MouseMove += gridView2_MouseMove;
            gridView2.MouseUp += (sender, e) => {
                isResizingColumnPanel = false;
            };

        }

        private void Test2_Load(Object sender, EventArgs e)
        {
            Thread.CurrentThread.CurrentCulture = new System.Globalization.CultureInfo("es-CL");
            Thread.CurrentThread.CurrentUICulture = new System.Globalization.CultureInfo("es-CL");

        }

        bool isResizingColumnPanel = false;
        private void gridView2_MouseMove(object sender, MouseEventArgs e)
        {
            var columnPanelBounds = ((GridViewInfo)gridView2.GetViewInfo()).ViewRects.ColumnPanel;

            if (isResizingColumnPanel)
            {
                gridView2.ColumnPanelRowHeight = e.Y - columnPanelBounds.Top;
            }

            var isCursorAboveColumnPanel = Math.Abs(e.Y - columnPanelBounds.Bottom) < 5;
            var isLeftMouseButton = (e.Button & MouseButtons.Left) == MouseButtons.Left;

            if (!isCursorAboveColumnPanel)
            {
                gridControl2.Cursor = Cursors.Default;
                return;
            }
            gridControl2.Cursor = Cursors.SizeNS;

            if (!isResizingColumnPanel && isCursorAboveColumnPanel && isLeftMouseButton)
            {
                isResizingColumnPanel = true;
                return;
            }
        }
    }
}
